class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        res = []
        for i, a in enumerate(nums):
            if i and a == nums[i - 1]:
                continue
            l, r = i + 1, len(nums) - 1
            while l < r:
                s = a + nums[l] + nums[r]
                if s > 0:
                    r -= 1
                elif s < 0:
                    l += 1
                else:
                    res.append([a, nums[l], nums[r]])
                    l += 1
                    while nums[l] == nums[l - 1] and l < r:
                        l += 1
        return res

class Solution:
    def threeSum(self, nums):
        res = set()
        for i, a in enumerate(nums):
            seen = set()
            for b in nums[i + 1:]:
                c = -a - b
                if c in seen:
                    res.add(tuple(sorted((a, b, c))))
                seen.add(b)
        return [list(t) for t in res]

